                    var copy = structuredClone(source);
                    check(_instanceof(copy.when, Date), "Date should survive cloning");
                    check(_instanceof(copy.re, RegExp), "RegExp should survive cloning");
                    check(_instanceof(copy.map, Map), "Map should survive cloning as a Map");
                    check(_instanceof(copy.set, Set), "Set should survive cloning as a Set");
