                    v.searchParams["delete"]("x");
                    equal([
                        v.href,
                        v.search
                    ], [
                        "http://example.com/",
                        ""
                    ], "no-op delete drops a bare ?");
                    var w = new U("http://www.example.com/?a=b,c");
                    equal([
                        w.toString(),
                        w.searchParams.toString()
                    ], [
                        "http://www.example.com/?a=b,c",
                        "a=b%2Cc"
                    ], "URL keeps its own query until params change");
                    w.searchParams.append("x", "y");
