                    var got = [];
                    var e = params.entries();
                    for(var step = e.next(); !step.done; step = e.next()){
                        it.search = "x=1&y=2&z=3";
                        got.push(step.value);
                    }
                    equal(got, [
                        [
                            "a",
                            "1"
                        ],
                        [
                            "y",
                            "2"
                        ],
                        [
                            "z",
                            "3"
                        ]
                    ], "iteration sees search changes");
